<script setup lang="ts">
import { ref } from 'vue'
const props = defineProps<{ context: 'npc' | 'grounding'; selected?: string[] }>()
const reviewId=ref(''), selection=ref(''), bundle=ref(''), grant=ref(''), transaction=ref(''), plan=ref('')
const host=ref('127.0.0.1'), port=ref(8766), origin=ref('http://127.0.0.1:8766'), generation=ref(1)
const tlsCert=ref(''), tlsKey=ref(''), expiresIn=ref(86400), pageLimit=ref(50)
const retractEvent=ref(''), retractRevision=ref(1), retractReason=ref('')
const cursor=ref(''), historyItem=ref(''), decisionRevision=ref(0), rerunMode=ref<'unresolved'|'selected'>('unresolved')
const dependencyPlan=ref(''), scopeKind=ref<'global'|'chapter'|'scene'|'location'|'document'|'evidence'>('global'), scopeValue=ref('')
const operationFile=ref(''), itemId=ref(''), checkSelection=ref(''), selectionSha=ref(''), targetKind=ref<'source'|'draft'>('draft'), replacement=ref(''), proposalId=ref(''), proposalSha=ref(''), identityReceipt=ref(''), guardResolution=ref(''), guardResolutionSha=ref(''), guardNote=ref(''), executeRegeneration=ref(false), documentSha=ref(''), npcDraftSha=ref(''), reviewer=ref('GM')
const busy=ref(false), note=ref(''), capabilityUrl=ref(''), result=ref('')
async function request(path:string, method:'GET'|'POST'='POST', payload?:object) {
  busy.value=true; note.value=''
  try { const response=await fetch(`/api/reviews${path}`,{method,headers:payload?{'Content-Type':'application/json'}:undefined,body:payload?JSON.stringify(payload):undefined}); const body=await response.json()
    if(!response.ok||body.ok===false) throw new Error(body.message||body.detail||`Review command failed (${response.status})`)
    reviewId.value=body.data?.review_id||reviewId.value; generation.value=body.data?.generation||generation.value; grant.value=body.data?.grant_id||grant.value; if(path.includes("/dependencies/migrate")) dependencyPlan.value=body.data?.plan_sha256||dependencyPlan.value; else plan.value=body.data?.plan_sha256||plan.value; result.value=JSON.stringify(body.data??body,null,2)
    capabilityUrl.value=body.data?.capability_url||body.data?.url||''; note.value=body.message||'Completed.'; return body
  } catch(error) { note.value=error instanceof Error?error.message:String(error); return null } finally { busy.value=false }
}
async function requestStream(path:string, payload:object) {
  busy.value=true; note.value='Running selected producers…'; result.value=''
  try {
    const response=await fetch(`/api/reviews${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})
    if(!response.ok||!response.body) throw new Error(`Review run failed (${response.status})`)
    const reader=response.body.getReader(), decoder=new TextDecoder(); let output=''
    while(true){const {done,value}=await reader.read();if(done)break;output+=decoder.decode(value,{stream:true});result.value=output}
    note.value='Regeneration run finished. Generated prose still requires review and exact sign-off.'
  } catch(error) { note.value=error instanceof Error?error.message:String(error) } finally { busy.value=false }
}
const rid=()=>encodeURIComponent(reviewId.value.trim())
function openCapability(){if(capabilityUrl.value) window.open(capabilityUrl.value,'_blank','noopener,noreferrer')}
function openWholeBundlePromotion(){document.querySelector('[data-test="grounding-promotion-preview"]')?.scrollIntoView({behavior:'smooth',block:'start'})}
</script>
<template>
  <section class="review-launcher" aria-labelledby="review-launcher-title">
    <h2 id="review-launcher-title">Shared review</h2><p>Create and manage a private review queue. Decisions remain separate from correction and publication actions.</p>
    <p v-if="props.selected?.length">{{ props.selected.length }} NPC subjects are selected in the dossier view. Save the literal dossier paths in the selection file below before creating the review.</p>
    <label>Selection file <input v-model="selection" placeholder="campaign/selections/npcs.json"></label><label>Review ID <input v-model="reviewId"></label><label>Expected generation <input v-model.number="generation" type="number" min="1"></label>
    <div class="actions">
      <button :disabled="busy||!selection" @click="request('/create','POST',{kind:props.context==='npc'?'npc_verification':'grounding_documents',selection})">Create selected review</button>
      <button :disabled="busy" @click="request('/init','POST',{})">Initialize</button><button :disabled="busy" @click="request('/migrate','POST',{dry_run:true})">Preview migration</button><button :disabled="busy||!plan" @click="request('/migrate','POST',{plan_sha256:plan})">Apply migration</button>
      <button :disabled="busy" @click="request('','GET')">List reviews</button><button :disabled="busy||!reviewId" @click="request(`/${rid()}/status`,'GET')">Refresh status</button><button :disabled="busy||!reviewId" @click="request(`/${rid()}?limit=${pageLimit}${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`,'GET')">Queue page</button><button :disabled="busy||!reviewId||!itemId" @click="request(`/${rid()}?item=${encodeURIComponent(itemId)}`,'GET')">Read item</button>
      <button :disabled="busy||!reviewId" @click="request(`/${rid()}/access/issue`,'POST',{expires_in:expiresIn})">Issue private link</button>
      <button :disabled="busy||!reviewId" @click="request(`/${rid()}/service/start`,'POST',{host,port,origin,...(tlsCert&&tlsKey?{tls_cert:tlsCert,tls_key:tlsKey}:{})})">Start reviewer</button><button :disabled="busy||!reviewId" @click="request(`/${rid()}/service/status`,'GET')">Reviewer status</button><button :disabled="busy||!reviewId" @click="request(`/${rid()}/service/stop`,'POST',{})">Stop reviewer</button>
      <button :disabled="busy||!reviewId||!selection" @click="request(`/${rid()}/export`,'POST',{selection})">Export decisions</button><button :disabled="busy||!bundle" @click="request('/import','POST',{bundle,expected_generation:generation})">Import decisions</button><button :disabled="busy||!reviewId" @click="request(`/${rid()}/history${historyItem?`?item=${encodeURIComponent(historyItem)}`:''}`,'GET')">Decision history</button>
    </div>
    <label>Migration plan digest <input v-model="plan"></label><button :disabled="busy" @click="request('/dependencies/migrate','POST',{dry_run:true})">Preview dependency adoption</button><label>Dependency plan digest <input v-model="dependencyPlan"></label><button :disabled="busy||!dependencyPlan" @click="request('/dependencies/migrate','POST',{plan_sha256:dependencyPlan})">Apply dependency adoption</button><label>Import bundle <input v-model="bundle"></label><label>Queue cursor <input v-model="cursor"></label><label>History item filter <input v-model="historyItem"></label>
    <fieldset><legend>Private reviewer endpoint</legend><label>Host <input v-model="host"></label><label>Port <input v-model.number="port" type="number"></label><label>Origin <input v-model="origin"></label><label>TLS certificate <input v-model="tlsCert"></label><label>TLS key <input v-model="tlsKey"></label><label>Grant lifetime seconds <input v-model.number="expiresIn" type="number" min="60"></label><label>Queue page size <input v-model.number="pageLimit" type="number" min="1"></label></fieldset>
    <div v-if="capabilityUrl" class="capability"><p>The capability link is shown once. Copy it now or open it directly.</p><code>{{ capabilityUrl }}</code><button @click="openCapability">Open private queue</button></div>
    <label>Grant ID <input v-model="grant"></label><button :disabled="busy||!reviewId||!grant" @click="request(`/${rid()}/access/revoke`,'POST',{grant})">Revoke link</button>
    <fieldset><legend>Withdraw a decision</legend><label>Event ID <input v-model="retractEvent"></label><label>Expected decision revision <input v-model.number="retractRevision" type="number" min="1"></label><label>Reason <input v-model="retractReason"></label><button :disabled="busy||!reviewId||!retractEvent||!retractReason" @click="request(`/${rid()}/retract`,'POST',{event:retractEvent,expected_decision_revision:retractRevision,reason:retractReason})">Withdraw decision</button></fieldset>
    <fieldset><legend>Refresh and selected checks</legend><button :disabled="busy||!reviewId" @click="request(`/${rid()}/refresh`,'POST',{expected_generation:generation})">Refresh custody</button><label>Finding or operation file <input v-model="operationFile"></label><button :disabled="busy||!reviewId||!operationFile" @click="request(`/${rid()}/findings?expected_generation=${generation}`,'POST',{selection:operationFile})">Add attributed findings</button><label>Rerun selection file <input v-model="checkSelection"></label><label>Rerun mode <select v-model="rerunMode"><option value="unresolved">Current unresolved only</option><option value="selected">Exact selected items</option></select></label><button :disabled="busy||!reviewId||!checkSelection" @click="request(`/${rid()}/rerun/preview`,'POST',{selection:checkSelection,mode:rerunMode})">Preview rerun</button><label>Selection digest <input v-model="selectionSha"></label><button :disabled="busy||!reviewId||!selectionSha" @click="request(`/${rid()}/rerun/run`,'POST',{selection_sha256:selectionSha})">Run exact checks</button></fieldset>
    <fieldset><legend>Correction, identity, and publication</legend><label>Item ID <input v-model="itemId"></label><label>Current expected decision revision <input v-model.number="decisionRevision" type="number" min="0"></label><label>Correction target <select v-model="targetKind"><option value="draft">Authored draft</option><option value="source">Maintained summary source</option></select></label><label>Exact replacement <input v-model="replacement"></label><button :disabled="busy||!reviewId||!itemId||!replacement" @click="request(`/${rid()}/correction/prepare`,'POST',{item:itemId,target_kind:targetKind,replacement,expected_decision_revision:decisionRevision})">Preview correction</button><label>Proposal ID <input v-model="proposalId"></label><label>Proposal digest <input v-model="proposalSha"></label><button :disabled="busy||!reviewId||!proposalId||!proposalSha" @click="request(`/${rid()}/correction/apply`,'POST',{proposal:proposalId,proposal_sha256:proposalSha})">Apply reviewed correction</button><label>Identity scope <select v-model="scopeKind"><option value="global">Global</option><option value="chapter">Chapter</option><option value="scene">Scene</option><option value="location">Location</option><option value="document">Document</option><option value="evidence">Evidence</option></select></label><label v-if="scopeKind!=='global'">Scope value <input v-model="scopeValue"></label><button :disabled="busy||!reviewId||!itemId" @click="request(`/${rid()}/identity/prepare`,'POST',{item:itemId,expected_decision_revision:decisionRevision,scope_kind:scopeKind,...(scopeKind!=='global'?{scope_value:scopeValue}:{})})">Prepare both identity alternatives</button><button :disabled="busy||!reviewId||!proposalId" @click="request(`/${rid()}/identity/${encodeURIComponent(proposalId)}`,'GET')">Show identity proposal</button><button :disabled="busy||!reviewId||!proposalId||!proposalSha" @click="request(`/${rid()}/identity/apply`,'POST',{proposal:proposalId,proposal_sha256:proposalSha})">Apply reviewed identity</button><button :disabled="busy||!reviewId||!proposalId" @click="request(`/${rid()}/identity/${encodeURIComponent(proposalId)}/resolution`,'GET')">Show separate conflict resolution</button><label>Guard resolution note <input v-model="guardNote"></label><button :disabled="busy||!reviewId||!proposalId||!guardNote" @click="request(`/${rid()}/identity/guard/prepare`,'POST',{proposal:proposalId,reviewer,note:guardNote})">Prepare exact guard resolution</button><label>Guard resolution ID <input v-model="guardResolution"></label><label>Guard resolution digest <input v-model="guardResolutionSha"></label><button :disabled="busy||!reviewId||!guardResolution||!guardResolutionSha" @click="request(`/${rid()}/identity/guard/apply`,'POST',{resolution:guardResolution,resolution_sha256:guardResolutionSha})">Apply reviewed guard resolution</button><label>Identity application receipt <input v-model="identityReceipt"></label><label><input v-model="executeRegeneration" type="checkbox"> Execute through the long-running local stream</label><button :disabled="busy||!reviewId||!identityReceipt||!operationFile" @click="executeRegeneration?requestStream(`/${rid()}/identity/regenerate`,{receipt:identityReceipt,selection:operationFile,execute:true}):request(`/${rid()}/identity/regenerate`,'POST',{receipt:identityReceipt,selection:operationFile})">Prepare or execute selected affected regeneration</button><label>Exact NPC draft digest <input v-model="npcDraftSha"></label><button :disabled="busy||!reviewId||!itemId||!npcDraftSha" @click="request(`/${rid()}/npc/sign`,'POST',{item:itemId,draft_sha256:npcDraftSha,expected_decision_revision:decisionRevision,reviewer})">Sign verified NPC draft</button><label>Exact document digest <input v-model="documentSha"></label><label>Reviewer <input v-model="reviewer"></label><button :disabled="busy||!reviewId||!itemId||!documentSha" @click="request(`/${rid()}/document/sign`,'POST',{item:itemId,document_sha256:documentSha,expected_decision_revision:decisionRevision,reviewer})">Sign exact document</button><p>The per-document prepare and promote actions are retired. Keep using decision history and exact document sign-offs here, then preview and publish the complete four-document bundle with its timeline, references, retained records, and dependencies.</p><button type="button" @click="openWholeBundlePromotion">Go to whole-bundle promotion</button></fieldset>
    <label>Recovery transaction <input v-model="transaction"></label><button :disabled="busy||!transaction" @click="request('/recover','POST',{transaction})">Recover</button><p aria-live="polite">{{ note }}</p><pre v-if="result" aria-label="Review command result">{{ result }}</pre>
  </section>
</template>
<style scoped>.review-launcher{border:1px solid var(--border-color,#8886);border-radius:.5rem;margin-block:1rem;padding:1rem}.actions{display:flex;flex-wrap:wrap;gap:.5rem;margin-block:.75rem}label{display:block;margin-block:.5rem}input{min-width:min(28rem,100%)}button{min-height:2.5rem}.capability,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;max-height:24rem;overflow:auto}fieldset{margin-block:.75rem}</style>
